package com.opensocket.aievent.core.a2a;
import java.time.OffsetDateTime; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.context.annotation.Profile; import org.springframework.stereotype.Repository;
@Repository @Profile("!prod") @ConditionalOnProperty(prefix="task",name="store",havingValue="MEMORY",matchIfMissing=true) public class InMemoryA2AResultQuarantineRepository implements A2AResultQuarantineRepository { private final Map<String,A2AResultQuarantine> values=new ConcurrentHashMap<>(); private String k(String t,String id){return t+"|"+id;} public A2AResultQuarantine save(A2AResultQuarantine q){values.put(k(q.getTenantId(),q.getQuarantineId()),q);return q;} public Optional<A2AResultQuarantine> findById(String t,String id){return Optional.ofNullable(values.get(k(t,id)));} public Optional<A2AResultQuarantine> findByAttempt(String t,String id){return values.values().stream().filter(v->t.equals(v.getTenantId())&&id.equals(v.getAttemptId())).findFirst();} public List<A2AResultQuarantine> findOpen(String t,int l){return values.values().stream().filter(v->t.equals(v.getTenantId())&&"OPEN".equals(v.getStatus())).limit(l).toList();} public List<A2AResultQuarantine> findByRequest(String t,String id,int l){return values.values().stream().filter(v->t.equals(v.getTenantId())&&id.equals(v.getRequestId())).sorted(java.util.Comparator.comparing(A2AResultQuarantine::getQuarantinedAt,java.util.Comparator.nullsLast(java.util.Comparator.naturalOrder())).reversed()).limit(l).toList();} public boolean resolveExpectedStatus(String t,String id,String e,String target,String by,String reason,OffsetDateTime at){A2AResultQuarantine q=values.get(k(t,id));if(q==null||!Objects.equals(e,q.getStatus()))return false;q.setStatus(target);q.setResolvedBy(by);q.setResolutionReason(reason);q.setResolvedAt(at);return true;} public String mode(){return "MEMORY";} }
